fun statusText(): String {
        return when (ttsState) {
            TtsState.INITIALIZING -> "tts=initializing"
            TtsState.READY -> "tts=ready"
            TtsState.FAILED -> "tts=init_failed"
            TtsState.LANGUAGE_UNSUPPORTED -> "tts=korean_unsupported"
            TtsState.CLOSED -> "tts=closed"
        }
    }

    private fun speak(
        message: String,
        priority: SpeechPriority,
        onCompleted: (() -> Unit)? = null,
        onFailed: (() -> Unit)? = null,
        riskRank: Int? = null,
        advisoryStartDeadlineMs: Long? = null,
        advisoryStartValidator: (() -> Boolean)? = null,
    ): NavigationSpeechDispatchResult {
        if (message.isBlank()) return NavigationSpeechDispatchResult.SUPPRESSED
        when (ttsState) {
            TtsState.INITIALIZING -> {
                // Navigation owns an explicit speech-ack state machine and must be retried there
                // after initialization. Queuing it here would speak once without acknowledging
                // the guide, then repeat the same instruction on the next location update.
                // Automatic risk feedback is retried by WalkSafeFeedbackPolicy as long as the
                // candidate remains current; queuing it here could speak after that risk vanished.
                if (priority == SpeechPriority.INTERACTION) {
                    pendingSpeechQueue.offer(message, priority, riskRank)
                }
                return NavigationSpeechDispatchResult.UNAVAILABLE
            }
            TtsState.READY -> Unit
            TtsState.FAILED,
            TtsState.LANGUAGE_UNSUPPORTED,
            TtsState.CLOSED,
            -> return NavigationSpeechDispatchResult.UNAVAILABLE

private fun processReportCandidate(
        candidate: AndroidReportCandidate,
        output: TrackedObjectDepth,
        reportImage: ByteArray?,
        trustedLocation: TrustedLocation,
        explicitRequest: Boolean = false,
    ): String {
        if (!reportPrivacyConsentSession.isGranted()) {
            return "reportCandidate=blocked:privacy_consent_required"
        }
        val gatewaySession = gatewaySessionOrNull(reason = "report", speak = explicitRequest)
            ?: return "reportCandidate=blocked:gateway_session_required"
        val spatialScope = AndroidReportCooldownPolicy.spatialScopeOrNull(
            actorId = gatewaySession.actorId,
            className = output.className,
            location = trustedLocation,
        ) ?: return "reportCandidate=blocked:spatial_key_invalid"
        val imageJpeg = reportImage ?: return "reportCandidate=blocked:no_report_image"
        val stateNowMs = System.currentTimeMillis()
        val attemptResult = reportAttemptStore.acquire(
            scope = spatialScope,
            nowMs = stateNowMs,
            bypassAutomaticCooldown = explicitRequest,
        )
        if (attemptResult is AndroidReportAttemptResult.Blocked) {
            val blockedKeyToken = sha256Hex(attemptResult.storageKey.toByteArray()).take(12)
            val blockedStatus = when (attemptResult.reason) {
                AndroidReportAttemptBlockReason.IN_FLIGHT -> {
                    "reportCandidate=duplicate_inflight key=$blockedKeyToken count=${attemptResult.attemptCount}"
                }
                AndroidReportAttemptBlockReason.AUTOMATIC_COOLDOWN -> {
                    "reportCandidate=cooldown_spatial key=$blockedKeyToken remainingMs=${attemptResult.remainingMs} count=${attemptResult.attemptCount}"
                }
                AndroidReportAttemptBlockReason.RETRY_BACKOFF -> {
                    "reportCandidate=backoff key=$blockedKeyToken remainingMs=${attemptResult.remainingMs} count=${attemptResult.attemptCount}"
                }
                AndroidReportAttemptBlockReason.STATE_CAPACITY -> {
                    "reportCandidate=blocked:state_capacity key=$blockedKeyToken"
                }
            }
            if (explicitRequest && attemptResult.reason == AndroidReportAttemptBlockReason.IN_FLIGHT) {
                speakInteraction("이미 신고가 진행 중입니다.")
            }

fun uploadCall(
        session: GatewayFieldSession,
        metadataJson: String,
        imageJpeg: ByteArray,
    ): CancellableNetworkCall<ReportUploadResponse> = cancellableHttpCall { cancellation ->
        val endpoint = session.gatewayBaseUrl.trimEnd('/') + "/api/reports/v2"
        val boundary = "----walksafe-${System.currentTimeMillis()}"
        val connection = URL(endpoint).openConnection() as HttpURLConnection
        cancellation.attach(connection)
        try {
            connection.apply {
                requestMethod = "POST"
                connectTimeout = 8_000
                readTimeout = 12_000
                doOutput = true
                doInput = true
                instanceFollowRedirects = false
                setRequestProperty("Accept", "application/json")
                setRequestProperty("Connection", "close")
                setRequestProperty("Content-Type", "multipart/form-data; boundary=$boundary")
                session.requestHeaders().forEach(::setRequestProperty)
            }
            connection.outputStream.use { output ->
                cancellation.attach(output)
                try {
                    writeMultipart(output, boundary, metadataJson, imageJpeg)
                } finally {
                    cancellation.detach(output)
                }
            }
            val response = connection.readBoundedResponse(REPORT_UPLOAD_MAX_RESPONSE_BYTES, cancellation)
            if (response.statusCode !in 200..299) {
                throw ReportUploadHttpException(
                    ReportUploadError(
                        statusCode = response.statusCode,
                        errorBody = response.body,
                        retryAfterMs = connection.getHeaderField("Retry-After")
                            ?.trim()
                            ?.toLongOrNull()
                            ?.coerceIn(1L, MAX_SERVER_RETRY_AFTER_MS / 1_000L)
                            ?.times(1_000L),
                    ),
                )
            }
            validatedReportUploadResponseOrNull(response.statusCode, response.body)
                ?: throw ReportUploadProtocolException()
        } finally {
            cancellation.detach(connection)
            connection.disconnect()
        }
    }

