/** In-memory consent and cancellation boundary for privacy-sensitive report uploads. */
class ReportPrivacyConsentSession {
    private val lock = Any()
    private val activeCalls = ActiveNetworkCalls()
    private var granted = false

    fun grant(): Boolean {
        return synchronized(lock) {
            val changed = !granted
            granted = true
            changed
        }
    }

    fun withdraw(): Boolean {
        return synchronized(lock) {
            val changed = granted
            granted = false
            activeCalls.cancelAll()
            changed
        }
    }

    fun isGranted(): Boolean = synchronized(lock) { granted }

    fun <T> trackIfGranted(call: CancellableNetworkCall<T>): CancellableNetworkCall<T>? {
        return synchronized(lock) {
            if (!granted) {
                call.cancel()
                null
            } else {
                activeCalls.track(call)
            }
        }
    }

    fun complete(call: CancellableNetworkCall<*>) {
        activeCalls.complete(call)
    }
}

